const item = $input.first().json;
const body = item.body || item;
const trim = v => String(v == null ? '' : v).trim();

const content     = trim(body.content);
const senderType  = (body.sender && body.sender.type) || body.sender_type || (body.conversation && body.conversation.meta && body.conversation.meta.sender && body.conversation.meta.sender.type) || '';
const messageType = body.message_type;
const isIncoming  = messageType === 'incoming' || messageType === 0 || messageType === '0';
const isPrivate   = Boolean(body.private);

const shouldProcess = body.event === 'message_created'
  && isIncoming
  && senderType === 'contact'
  && !isPrivate
  && content.length > 0;

// Order ID detection
const rxBefore  = /(?:order|pedido|encomenda|n[uú]mero)\D{0,15}(\d{4,})\b/i;
const rxAfter   = /\b(\d{5,})\D{0,15}(?:order|pedido|encomenda|status)/i;
const rxHash    = content.match(/(?:^|\s)#(\d{4,})\b/);
const rxAlone   = content.match(/^\s*(\d{5,})\s*$/);
const rxBeforeM = content.match(rxBefore);
const rxAfterM  = content.match(rxAfter);
const detectedOrderId = (rxBeforeM && rxBeforeM[1])
  || (rxAfterM && rxAfterM[1])
  || (rxHash && rxHash[1])
  || (rxAlone && rxAlone[1])
  || '';

const senderEmail = trim((body.sender && body.sender.email) || (body.conversation && body.conversation.meta && body.conversation.meta.sender && body.conversation.meta.sender.email) || '');
const senderName  = trim((body.sender && body.sender.name)  || (body.conversation && body.conversation.meta && body.conversation.meta.sender && body.conversation.meta.sender.name)  || '');
const senderPhone = trim((body.sender && body.sender.phone_number) || (body.conversation && body.conversation.meta && body.conversation.meta.sender && body.conversation.meta.sender.phone_number) || '');

return {
  route: shouldProcess ? 'process' : 'ignore',
  event: body.event || '',
  conversationId: (body.conversation && body.conversation.id) || body.conversation_id || null,
  accountId: (body.account && body.account.id) || body.account_id || null,
  inboxId: (body.inbox && body.inbox.id) || body.inbox_id || (body.conversation && body.conversation.inbox_id) || null,
  content,
  senderEmail,
  senderName,
  senderPhone,
  detectedOrderId,
  config: {
    chatwootBaseUrl: 'https://sac.famivita.com',
    wooBaseUrl: 'https://www.famivita.com.br',
    openAiModel: 'gpt-4.1-mini',
    maxConversationMessages: 24,
    shippingApiUrl: 'https://www.famivita.com.br/wp-json/custom-shipping/v1/quote-get',
    defaultItemWeightKg: 0.5
  }
};

const ctx = $('Normalize Event').first().json;
const convo = $('Get Conversation').first().json || {};
const orderResp = $('Maybe Lookup Order').first().json || {};
const order = orderResp.body || orderResp;
const catalogRaw = $('Get Catalog').all().map(x => x.json).filter(Boolean);

const stripHtml = v => String(v || '').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();

// ── Catalog enrichment ──
const wooBase = ctx.config.wooBaseUrl;
const getCol = (row, ...cands) => {
  for (const c of cands) if (row[c] !== undefined && row[c] !== null) return row[c];
  const keys = Object.keys(row);
  for (const c of cands) {
    const want = String(c).trim().toLowerCase().replace(/[\s_-]+/g,'');
    const k = keys.find(k => String(k).trim().toLowerCase().replace(/[\s_-]+/g,'') === want);
    if (k && row[k] !== undefined && row[k] !== null) return row[k];
  }
  return '';
};
const pickPrice = r => String(getCol(r,'price','sale_price','regular_price') || '').trim();

const catalogEnriched = catalogRaw.map(r => {
  const productId   = Number(getCol(r,'product_id','id') || 0) || null;
  const variationId = Number(getCol(r,'variation_id','var_id') || 0) || null;
  const cartId      = variationId || productId;
  const title       = String(getCol(r,'custom_title','product_title','title','name') || '').trim();
  const altName     = String(getCol(r,'custom_text') || '').trim();
  const extraText   = [getCol(r,'custom_text1'), getCol(r,'custom_text2')].map(v => stripHtml(v||'')).filter(Boolean).join(' ').slice(0,300);
  const stockStatus = String(getCol(r,'stock_status') || '').trim().toLowerCase();
  const isOos = stockStatus === 'outofstock' || stockStatus === 'out_of_stock' || stockStatus === 'out-of-stock';
  const isBackorder = stockStatus === 'onbackorder' || stockStatus === 'on_backorder' || stockStatus === 'on-backorder';
  const titleSuffix = isOos ? ' ❌ ESGOTADO' : (isBackorder ? ' ⏳ Pré-venda' : '');
  const stockLine   = stockStatus ? ('Estoque: ' + stockStatus) : '';
  const addToCart   = (isOos || !cartId) ? '' : (wooBase + '/carrinho-de-compras/?add-to-cart=' + cartId);
  return {
    product_id: productId,
    variation_id: variationId,
    title,
    alt_name: altName,
    sku: String(getCol(r,'product_sku','sku') || '').trim(),
    url: String(getCol(r,'product_url','url') || '').trim(),
    add_to_cart: addToCart,
    price: pickPrice(r),
    short: extraText,
    tags: String(getCol(r,'product_tags','tags') || '').trim(),
    manufacturer: String(getCol(r,'product_manufacturer','manufacturer') || '').trim(),
    weight_kg: Number(getCol(r,'weight_kg','weight') || ctx.config.defaultItemWeightKg) || ctx.config.defaultItemWeightKg,
    status: String(getCol(r,'status') || '').trim().toLowerCase(),
    stock_status: stockStatus,
    title_suffix: titleSuffix,
    stock_line: stockLine
  };
});

const catalogAll = catalogEnriched
  .filter(p => p.title || p.alt_name)
  .filter(p => !p.status || p.status === 'publish');

// ── Conversation history (oldest → newest) ──
const rawMsgs = Array.isArray(convo.payload) ? convo.payload
  : (Array.isArray(convo.data && convo.data.payload) ? convo.data.payload
  : (Array.isArray(convo) ? convo : []));
const sorted = rawMsgs
  .filter(m => !m.private && m.message_type !== 'activity' && m.message_type !== 2)
  .sort((a,b) => (a.created_at||0) - (b.created_at||0))
  .slice(-ctx.config.maxConversationMessages);
const history = sorted.map(m => {
  const role = (m.message_type === 'incoming' || m.message_type === 0) ? 'user' : 'assistant';
  return { role, content: stripHtml(m.content || '') };
}).filter(m => m.content);

// ── Detect price filter from latest user message ──
const lastUserMsg = ((history.filter(m => m.role === 'user').slice(-1)[0]) || { content: '' }).content;
const detectPriceFilter = (msgRaw) => {
  const t = norm(msgRaw);
  const num = g => Number.parseFloat(String(g).replace(/\./g,'').replace(',', '.')) || 0;
  let m = t.match(/(?:entre|between)\s+r?\$?\s*(\d+(?:[.,]\d+)?)\s+(?:e|and|to|ate)\s+r?\$?\s*(\d+(?:[.,]\d+)?)/);
  if (m) return { type: 'range', min: num(m[1]), max: num(m[2]) };
  m = t.match(/(?:abaixo de|menos de|ate|no maximo|max(?:imo)?(?: de)?|below|less than|under|cheaper than|no more than|maximo)\s+r?\$?\s*(\d+(?:[.,]\d+)?)/);
  if (m) return { type: 'max', value: num(m[1]) };
  m = t.match(/(?:acima de|mais de|maior que|above|more than|over|at least|pelo menos)\s+r?\$?\s*(\d+(?:[.,]\d+)?)/);
  if (m) return { type: 'min', value: num(m[1]) };
  return null;
};
const parsePrice = v => {
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
  const s = String(v||'').replace(/[^0-9,.\-]/g,'').trim();
  if (!s) return 0;
  const cleaned = s.includes(',') && s.includes('.') ? s.replace(/\./g,'').replace(',', '.') : s.replace(',', '.');
  const n = Number.parseFloat(cleaned);
  return Number.isFinite(n) ? n : 0;
};
const priceFilter = detectPriceFilter(lastUserMsg);
let priceFilteredCatalog = catalogAll;
if (priceFilter) {
  priceFilteredCatalog = catalogAll.filter(p => {
    const price = parsePrice(p.price);
    if (price <= 0) return false;
    if (priceFilter.type === 'max')   return price <= priceFilter.value;
    if (priceFilter.type === 'min')   return price >= priceFilter.value;
    if (priceFilter.type === 'range') return price >= priceFilter.min && price <= priceFilter.max;
    return true;
  });
  if (priceFilter.type === 'max') priceFilteredCatalog.sort((a,b) => parsePrice(a.price) - parsePrice(b.price));
  else if (priceFilter.type === 'min') priceFilteredCatalog.sort((a,b) => parsePrice(b.price) - parsePrice(a.price));
}

// ── Keyword ranking ──
const STOPWORDS = new Set(['the','and','for','com','para','que','meu','minha','seu','sua','sobre','quero','preciso','send','tell','show','give','need','want','have','this','that','here','there','please','olá','ola','oi','bom','boa','dia','tarde','noite','obrigado','obrigada','por','favor','são','sao','não','nao','sim','também','tambem','muito','mais','menos','tudo','nada','product','products','produto','produtos','detail','details','detalhe','detalhes','gostaria','poderia','sabe','dizer','onde','quanto','como','qual','quais']);
const tokens = norm(lastUserMsg).split(/[^a-z0-9]+/).filter(w => w.length >= 3 && !STOPWORDS.has(w));
const scoreRow = row => {
  if (tokens.length === 0) return 0;
  const titleHay = norm([row.title, row.alt_name].join(' '));
  const otherHay = norm([row.short, row.tags, row.manufacturer, row.sku, row.url].join(' '));
  let s = 0;
  for (const t of tokens) {
    if (titleHay.includes(t)) s += 3;
    else if (otherHay.includes(t)) s += 1;
  }
  return s;
};
const scored = priceFilteredCatalog.map(r => ({ row: r, score: scoreRow(r) }));
scored.sort((a,b) => b.score - a.score);
const VISIBLE_LIMIT = 150;
const catalog = scored.slice(0, VISIBLE_LIMIT).map(s => s.row);

// ── Detect active order item from prior assistant messages ──
let activeOrderItem = null;
const recentAssistant = history.filter(m => m.role === 'assistant').slice(-4);
for (let i = recentAssistant.length - 1; i >= 0; i--) {
  const msg = recentAssistant[i].content || '';
  const safeIds = [];
  let mm; const rx = /add-to-cart=(\d+)/g;
  while ((mm = rx.exec(msg)) !== null) safeIds.push(Number(mm[1]));
  if (safeIds.length === 1) {
    const id = safeIds[0];
    const cat = catalogAll.find(p => Number(p.variation_id) === id || Number(p.product_id) === id);
    if (cat) {
      activeOrderItem = { product_id: cat.product_id, variation_id: cat.variation_id, title: cat.title, price: cat.price, stock_status: cat.stock_status };
      break;
    }
  } else if (safeIds.length > 1) {
    break; // ambiguous — let the AI decide based on user's selection
  }
}

// ── User picked an explicit option number (1, 2, 3...) ──
// If the prior assistant message numbered options, pull the chosen ID.
const lastUserMsgRaw = lastUserMsg.toLowerCase().trim();
const optionMatch = lastUserMsgRaw.match(/^(?:op[cç][aã]o\s*)?(?:n[uú]?mero\s*)?(\d{1,2})\b/) || lastUserMsgRaw.match(/\bop[cç][aã]o\s*(\d{1,2})\b/);
if (optionMatch && recentAssistant.length > 0) {
  const idx = Number(optionMatch[1]) - 1;
  const lastAssist = recentAssistant[recentAssistant.length - 1].content || '';
  const ids = [];
  let mm; const rx = /add-to-cart=(\d+)/g;
  while ((mm = rx.exec(lastAssist)) !== null) ids.push(Number(mm[1]));
  if (idx >= 0 && idx < ids.length) {
    const cat = catalogAll.find(p => Number(p.variation_id) === ids[idx] || Number(p.product_id) === ids[idx]);
    if (cat) activeOrderItem = { product_id: cat.product_id, variation_id: cat.variation_id, title: cat.title, price: cat.price, stock_status: cat.stock_status };
  }
}

// ── Variation attribute override ──
// If the customer's recent message specifies an attribute (60g, 168 cápsulas,
// 12 semanas, etc.) that doesn't match the current AOI's title, switch AOI to
// the matching variation in the same product family.
{
  const ATTR_RX = /\b(\d+\s*(?:g|ml|mg|kg|l|c[aá]psulas?|cap|comprimidos?|sach[eê]s?|tiras?|semanas?|meses?|unidades?|pares?|aplicadores?))\b/gi;
  const recentUserMsgs = history.filter(m => m.role === 'user').slice(-3);
  let userAttrs = [];
  for (let i = recentUserMsgs.length - 1; i >= 0; i--) {
    const msg = recentUserMsgs[i].content || '';
    const matches = [];
    let am;
    ATTR_RX.lastIndex = 0;
    while ((am = ATTR_RX.exec(msg.toLowerCase())) !== null) {
      matches.push(am[1].replace(/\s+/g, '').toLowerCase());
    }
    if (matches.length > 0) { userAttrs = matches; break; }
  }
  if (userAttrs.length > 0) {
    const titleHasAll = (cat, attrs) => {
      const t = norm(cat.title).replace(/\s+/g, '');
      return attrs.every(a => t.includes(a));
    };
    const aoiOk = activeOrderItem && titleHasAll(activeOrderItem, userAttrs);
    if (!aoiOk) {
      let candidates = activeOrderItem
        ? catalogAll.filter(p => Number(p.product_id) === Number(activeOrderItem.product_id))
        : catalogAll;
      let better = candidates.find(p => titleHasAll(p, userAttrs));
      if (!better && activeOrderItem) better = catalogAll.find(p => titleHasAll(p, userAttrs));
      if (better) {
        activeOrderItem = {
          product_id: better.product_id,
          variation_id: better.variation_id,
          title: better.title,
          price: better.price,
          stock_status: better.stock_status
        };
      }
    }
  }
}

// ── Identity keys for workflow memory + ORDER_INFO ownership filter ──
const ownerEmail = String(ctx.senderEmail || '').trim().toLowerCase();
const ownerPhoneDigits = String(ctx.senderPhone || '').replace(/\D/g, '');
const ownerPhoneTail = ownerPhoneDigits.slice(-10);
const memoryKey = (ownerPhoneTail && ownerPhoneTail.length >= 8)
  ? ('p:' + ownerPhoneTail)
  : (ownerEmail ? ('e:' + ownerEmail) : '');

// ── Read previousBilling from workflow memory (static data) ──
// Saved by Build Order Confirmation after a successful order. Persists across
// executions inside this workflow's settings JSON.
let previousBilling = null;
try {
  const staticData = $getWorkflowStaticData('global');
  const memory = staticData.billingMemory || {};
  if (memoryKey && memory[memoryKey]) {
    const saved = memory[memoryKey];
    if (saved && saved.billing_postcode && saved.billing_address_1 && saved.billing_city) {
      previousBilling = saved;
    }
  }
} catch (e) { /* static data unavailable — fall through with null */ }

// ── Order context (status questions only — filtered to current contact) ──
const isOwnerOrder = (o) => {
  if (!o || !o.billing) return false;
  const e = String(o.billing.email || '').trim().toLowerCase();
  if (ownerEmail && e && e === ownerEmail) return true;
  if (ownerPhoneTail && ownerPhoneTail.length >= 8) {
    const p = String(o.billing.phone || '').replace(/\D/g, '').slice(-10);
    if (p && p === ownerPhoneTail) return true;
  }
  return false;
};
let orderInfo = null;
if (Array.isArray(order)) {
  const ownOrders = order.filter(isOwnerOrder);
  if (ownOrders.length > 0) {
    orderInfo = { kind: 'list', orders: ownOrders.slice(0,5).map(o => ({
      id: o.id, status: o.status, total: o.total, date: o.date_created,
      pay_url: o.payment_url || '', items: (o.line_items||[]).map(i => i.name)
    })) };
  }
} else if (order && order.id && isOwnerOrder(order)) {
  orderInfo = { kind: 'single', order: {
    id: order.id, status: order.status, total: order.total,
    date: order.date_created, pay_url: order.payment_url || '',
    items: (order.line_items||[]).map(i => ({ name: i.name, qty: i.quantity, total: i.total })),
    shipping_total: order.shipping_total, billing_email: (order.billing && order.billing.email)
  }};
}

// ── System prompt ──
const systemMessage = [
  'Você é uma atendente humana brasileira via WhatsApp para a Famivita (famivita.com.br), loja de bem-estar feminino.',
  'Fale natural, calorosa, em PT-BR. Use mensagens curtas (2-4 frases) e emojis com moderação. NUNCA diga que é IA, robô ou bot.',
  '',
  '═══════════ REGRAS CRÍTICAS ═══════════',
  '1. SEMPRE leia o histórico completo antes de responder. Nunca repita perguntas já respondidas.',
  '2. Saída SEMPRE em JSON estrito. Nada de texto fora do JSON.',
  '3. NUNCA invente nomes, IDs, preços ou URLs de produto. Use APENAS os valores do CATÁLOGO abaixo.',
  '4. NUNCA construa nem modifique URLs. Copie os campos url e add_to_cart letra por letra.',
  '',
  '═══════════ MOSTRAR PRODUTOS ═══════════',
  'Para mostrar produtos você DEVE fazer EXATAMENTE assim:',
  '  1. Inclua a chave "show_products" no JSON: array de variation_id (ou product_id quando não houver variação) extraídos do CATÁLOGO.',
  '  2. Coloque o token literal {PRODUCTS} dentro do campo "reply", no ponto onde os produtos devem aparecer.',
  '  3. NÃO escreva nomes, preços, links ou status de estoque dos produtos no "reply" — o sistema renderiza tudo automaticamente, numerado 1., 2., 3....',
  '',
  '🛑 ABSOLUTO — NUNCA ESCREVA O RODAPÉ DE PEDIDO:',
  '  O sistema adiciona automaticamente, abaixo dos produtos, um rodapé com:',
  '    "💬 Quer pedir por aqui mesmo pelo WhatsApp? Me diga a opção 1, 2, 3... e envie seus dados de cobrança no formato: Email, CEP, Endereço..."',
  '  VOCÊ NÃO DEVE escrever esse rodapé, nem qualquer variação dele ("Quer pedir...", "Me diga a opção 1, 2", "envie seus dados de cobrança", o template "Email: ... CEP: ... Endereço: ..."). O sistema cuida disso. Se você escrever, o cliente verá em duplicado.',
  '  Termine seu "reply" logo após o token {PRODUCTS}, sem instrução adicional sobre como pedir.',
  '',
  'Quando o cliente NÃO está pedindo para ver produtos (ex.: já está mandando dados de cobrança, confirmando pedido, perguntando sobre status), use show_products = [] e NÃO inclua {PRODUCTS}.',
  '',
  'VARIAÇÕES: o catálogo tem uma linha por variação (cada uma com seu variation_id e add_to_cart). Mostre cada variação como item próprio. Se o cliente especificar atributo ("60g", "168 cápsulas"), encontre a linha cujo título contenha família + atributo. Quando em dúvida, pergunte qual variação ele quer.',
  '',
  'ESTOQUE: para LISTAGEM, inclua produtos de TODOS os status (instock/outofstock/onbackorder) — o sistema marca cada um corretamente. Para PEDIDO, NUNCA inclua produto outofstock em items[].',
  '',
  '═══════════ FLUXO DE PEDIDO VIA WHATSAPP ═══════════',
  'STAGE 0 — VERIFICAÇÃO DE ESTOQUE:',
  '  Antes de qualquer outra coisa quando o cliente quer pedir um produto: olhe stock_status no CATÁLOGO.',
  '  Se outofstock → recuse o pedido e ofereça similares em estoque. action_after = "none".',
  '  Se instock → siga para STAGE 1.',
  '',
  'STAGE 1 — DADOS DE COBRANÇA:',
  '  Campos necessários (8): email, cpf, postcode (CEP), address_1 (rua), number, neighborhood (bairro), city, state (UF). Nome e telefone vêm do CUSTOMER_PROFILE.',
  '  ',
  '  ⭐ Se PREVIOUS_BILLING (mais abaixo) NÃO for null:',
  '    O cliente já tem endereço cadastrado. NÃO peça os dados novamente. Em vez disso:',
  '      a) Mostre um resumo curto do endereço salvo, ex.: "Vou usar seu endereço cadastrado: <Rua, nº, Bairro, Cidade/UF, CEP>. Posso confirmar?"',
  '      b) Se o cliente confirmar (sim, ok, pode usar, mesmo endereço, etc.) → siga DIRETO para STAGE 2 (calculate_shipping). Os dados já estão no sistema.',
  '      c) Se o cliente quiser alterar APENAS um ou poucos campos, peça SOMENTE esses campos.',
  '      d) Se o cliente quiser trocar todo o endereço, peça os 8 campos.',
  '    action_after permanece "none" enquanto o cliente não confirmar.',
  '  ',
  '  Se PREVIOUS_BILLING for null:',
  '    Cliente novo — peça os 8 campos em uma única mensagem curta. action_after = "none".',
  '',
  'STAGE 2 — PRÉ-VISUALIZAÇÃO COM FRETE:',
  '  Quando todos os campos estiverem preenchidos E o produto escolhido for in-stock:',
  '  action_after = "calculate_shipping"',
  '  action_data com items=[{product_id, variation_id, quantity}] e billing_*.',
  '  reply = string curta tipo "Um instante, calculando o frete...". O sistema substitui pelo preview formatado.',
  '',
  'STAGE 3 — CONFIRMAÇÃO:',
  '  Cliente confirma com "sim", "confirmo", "pode fechar":',
  '  action_after = "create_order"',
  '  action_data com todos os billing_*, items[], shipping_method, shipping_cost.',
  '  reply curto tipo "Ótimo, gerando seu pedido...". O sistema anexa o link de pagamento.',
  '',
  '═══════════ STATUS DE PEDIDO ═══════════',
  'Se o cliente perguntar sobre pedido existente, use ORDER_INFO. Traduza status:',
  '  pending → Aguardando pagamento (NÃO concluído)',
  '  processing → Em processamento (pagamento confirmado)',
  '  on-hold → Em espera   |   completed → Concluído / entregue',
  '  cancelled → Cancelado |   refunded → Reembolsado |   failed → Falhou',
  'Inclua pay_url quando status for pending ou on-hold.',
  'Se ORDER_INFO for null, peça o número do pedido ou o e-mail cadastrado.',
  '',
  '═══════════ ESQUEMA JSON DE SAÍDA ═══════════',
  '{',
  '  "reply": "string em PT-BR; use {PRODUCTS} onde os produtos devem aparecer",',
  '  "show_products": [594247, 1044937],',
  '  "action_after": "none" | "calculate_shipping" | "create_order",',
  '  "action_data": {',
  '    "items": [{ "product_id": 12345, "variation_id": 58, "quantity": 1 }],',
  '    "billing_name": "...",',
  '    "billing_email": "...",',
  '    "billing_cpf": "...",',
  '    "billing_phone": "...",',
  '    "billing_postcode": "...",',
  '    "billing_address_1": "...",',
  '    "billing_number": "...",',
  '    "billing_neighborhood": "...",',
  '    "billing_city": "...",',
  '    "billing_state": "...",',
  '    "shipping_method": "PAC",',
  '    "shipping_cost": 0',
  '  }',
  '}',
  'Use action_data = {} e show_products = [] quando não aplicável.',
  '',
  '═══════════ ITEM ATIVO DETECTADO ═══════════',
  activeOrderItem ? JSON.stringify(activeOrderItem) : 'null',
  '',
  '═══════════ CATÁLOGO (' + catalog.length + ' produtos) ═══════════',
  JSON.stringify(catalog),
  '',
  '═══════════ ORDER_INFO ═══════════',
  orderInfo ? JSON.stringify(orderInfo) : 'null',
  '',
